//! Handwritten compilation harness; each included module is generated by build.rs.
//! These are test fixtures, not an independently maintained Library implementation.
//!
//! Rust rejects wrong scalar and reference types:
//! ```compile_fail
//! use intersect_model::core::api::BasicModel;
//! use intersect_rust_bindings_tests::library::{self, BookCopy};
//! let mut model = BasicModel::new(library::schema().unwrap()).unwrap();
//! let copy = BookCopy::create(&mut model, "copy", "catalog").unwrap();
//! copy.set_edition(&mut model, Some("wrong"));
//! ```
//! ```compile_fail
//! use intersect_model::core::api::BasicModel;
//! use intersect_rust_bindings_tests::library::{self, BookCopy, Loan};
//! let mut model = BasicModel::new(library::schema().unwrap()).unwrap();
//! let copy = BookCopy::create(&mut model, "copy", "catalog").unwrap();
//! let loan = Loan::create(&mut model, "loan", "catalog").unwrap();
//! loan.set_member(&mut model, &copy);
//! ```
//! Abstract classes have no constructor; readonly computed features have no setter:
//! ```compile_fail
//! use intersect_rust_bindings_tests::library::Named;
//! let _ = Named::create;
//! ```
//! ```compile_fail
//! use intersect_model::core::{api::BasicModel, query::QueryBudget, storage::SettingContext};
//! use intersect_rust_bindings_tests::state::Item;
//! fn readonly(model: &mut BasicModel, item: &Item, context: SettingContext<'_>, budget: &mut QueryBudget) {
//!     item.set_locked_computed(model, None, context, budget);
//! }
//! ```

//! Unordered collections do not expose indexed editing methods:
//! ```compile_fail
//! use intersect_rust_bindings_tests::state::Item;
//! let _ = Item::insert_bag;
//! ```

pub mod library {
    include!(concat!(env!("OUT_DIR"), "/library.rs"));
}
pub mod shapes {
    include!(concat!(env!("OUT_DIR"), "/shapes.rs"));
}
pub mod programmatic {
    include!(concat!(env!("OUT_DIR"), "/programmatic.rs"));
}

